<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useArcade} from '../stores/arcade'
import {ticketKinds} from '../data/ticketKinds'
import CharacterPicker from './CharacterPicker.vue'
const s=useArcade(),selection=ref(null),dialog=ref(null),busy=ref(false),error=ref(''),notice=ref('');let requestKey=''
const tickets=computed(()=>s.data.tickets??[]),available=id=>tickets.value.filter(t=>t.kind===id&&t.remaining>0),count=id=>available(id).reduce((n,t)=>n+t.remaining,0)
function open(t){const gift=available(t.id)[0];if(!gift)return;selection.value={...t,giftId:gift.id};requestKey=crypto.randomUUID();error.value='';notice.value='';dialog.value.showModal()}
function changed(){notice.value='포켓몬 변경 1회권 1장을 사용했어요. 포인트는 차감되지 않았습니다.';dialog.value.close()}
async function escape(){if(busy.value||!selection.value)return;busy.value=true;error.value='';try{await s.petAction('diglett-restore',s.data.pet.diglettRecovery.id,requestKey,selection.value.giftId);notice.value='디그다 탈출권 1장을 사용해 원래 포켓몬으로 돌아왔어요!';dialog.value.close()}catch(e){error.value=e.message}finally{busy.value=false}}
async function refresh(){try{await s.refresh()}catch(e){error.value=e.message}}
onMounted(refresh);onUnmounted(()=>dialog.value?.close())
</script>
<template><section class="ticket-inventory" aria-label="내 사용권"><h3>내 사용권</h3><p>관리자 선물함에서 수령한 사용권입니다. 사용 시 1장씩 차감돼요.</p><button class="light" @click="refresh">사용권 새로고침</button><article v-for="t in ticketKinds" :key="t.id" class="ticket-card"><span class="ticket-icon" aria-hidden="true">{{t.icon}}</span><h3>{{t.name}}</h3><strong>보유 {{count(t.id)}}장</strong><p>{{t.description}}</p><button :disabled="!count(t.id)||busy||(t.id==='diglett-escape'&&!s.data.pet.diglettRecovery)||(t.id==='partner-change'&&s.data.pet.character==='diglett')" @click="open(t)">{{!count(t.id)?'보유한 사용권 없음':t.id==='diglett-escape'&&!s.data.pet.diglettRecovery?'디그다일 때 사용 가능':t.id==='partner-change'&&s.data.pet.character==='diglett'?'디그다 탈출 후 사용 가능':'사용하기'}}</button></article><p v-if="notice" role="status">{{notice}}</p><p v-if="error" role="alert">{{error}}</p><dialog ref="dialog" class="ticket-dialog ticket-use-dialog" aria-label="사용권 사용" @cancel.prevent="!busy&&dialog.close()"><button class="text-button ticket-close" aria-label="사용권 창 닫기" :disabled="busy" @click="dialog.close()">✕</button><template v-if="selection"><h2>{{selection.name}} 사용</h2><template v-if="selection.id==='partner-change'"><p>원하는 포켓몬을 고르면 사용권 1장이 차감됩니다. 레벨·아이템은 유지되고 강화는 1단계로 돌아갑니다.</p><CharacterPicker :model-value="s.data.pet.character" :locked="true" :ticket-id="selection.giftId" @changed="changed"/></template><template v-else><p>탈출권 1장을 사용해 원래 포켓몬의 1단계로 돌아갈까요? 레벨·보유 아이템·스킨은 유지됩니다.</p><button :disabled="busy||!s.data.pet.diglettRecovery" @click="escape">{{busy?'복구 중…':'탈출권 1장 사용하고 복구'}}</button></template></template><p v-if="error" role="alert">{{error}}</p></dialog></section></template>
<style scoped>
.ticket-inventory{min-width:0}.ticket-inventory>p,.ticket-card p{font-size:11px;line-height:1.8}.ticket-card{border:2px solid var(--rpg-mid);background:var(--rpg-paper);padding:14px;margin-top:12px;min-width:0}.ticket-card h3{font-size:14px;margin:8px 0}.ticket-card strong{font-size:12px}.ticket-icon{font-size:26px}.ticket-card button{width:100%;margin:4px 0 0;padding:10px 6px;font-size:11px;white-space:normal;line-height:1.5}.ticket-use-dialog{width:min(900px,calc(100vw - 28px))}
</style>
